#!/bin/bash
# Fault recipe: bulk outbound transfer (co-located workload container).
#
# A BENIGN SIMULATION on our own isolated VM: generated bytes sent to a listener inside the
# same container, at a steady rate. Nothing leaves the host, no real data is read, and no
# external address is contacted. What it reproduces is the SHAPE of bulk egress.
#
# THE QUESTION IT ASKS. Every network fault we have is about IMPAIRMENT - packets dropped,
# latency added. This is the opposite: the network works perfectly and is being used heavily.
# So it asks whether a blueprint can separate UNUSUAL traffic from HEAVY traffic, which is a
# different question from any we have posed and one where the honest answer may be "not from
# volume alone".
#
# The candidate discriminator is steadiness and direction: a long-lived connection moving a
# large volume ONE WAY at a CONSTANT rate with almost no reply traffic. Application traffic is
# bursty and bidirectional. If that holds it is a new signal; if it does not, it is a limit
# worth writing down.
#
# Naser, 2 Sept: "Mainly performance, but security can be a part of it as well."
#
# Pre-registered expectations: KERNEL only. Also visible to anyone watching host network
# counters, which is deliberate - it is the realistic detection path and a fair comparison.
#
# Usage:
#   ./data_exfiltration.sh inject [subtle|aggressive]
#   ./data_exfiltration.sh cleanup | status
set -euo pipefail
source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/fault_lib.sh"

FAULT_FAMILY="H_security"
FAULT_NAME="data_exfiltration"
FAULT_SCOPE="host"
TARGET_SERVICE="host"
EXPECTED_BLAST_RADIUS="${EXPECTED_BLAST_RADIUS:-[\"host network\"]}"
EXPECTED_WINNING_MODALITY="${EXPECTED_WINNING_MODALITY:-kernel}"
TARGET_TRACE_VISIBILITY="${TARGET_TRACE_VISIBILITY:-blind_spot}"
REMEDIATION="identify the process and its destination; egress filtering"

CONTAINER="data-exfiltration"

case "${1:-}" in
  inject)
    INTENSITY="${2:-aggressive}"
    case "$INTENSITY" in
      # subtle sits below normal application traffic on purpose: if volume alone were the
      # signal, subtle would be undetectable, and finding that out is the point
      subtle)     RATE="${RATE:-5}"  CHUNK="${CHUNK:-16}" CPUS="${CPUS:-0.5}" ;;
      aggressive) RATE="${RATE:-40}" CHUNK="${CHUNK:-64}" CPUS="${CPUS:-1.0}" ;;
      *) echo "unknown intensity: $INTENSITY"; exit 1 ;;
    esac
    workload_start "$CONTAINER" data_exfiltration.py "$CPUS" -- "$RATE" "$CHUNK"
    gt_begin "$INTENSITY" "{\"rate_mb_per_s\": $RATE, \"chunk_kb\": $CHUNK, \"cpus_cap\": $CPUS, \"container\": \"$CONTAINER\", \"note\": \"benign simulation; sink is a local listener, nothing leaves the host\"}"
    ;;
  cleanup)  workload_stop "$CONTAINER"; gt_end ;;
  status)   workload_status "$CONTAINER" ;;
  *) echo "usage: $0 inject [subtle|aggressive] | cleanup | status"; exit 1 ;;
esac
